auto computeHash = [&](float x, float y, float z) -> std::size_t {
    std::int64_t ix = static_cast<std::int64_t>(std::floor(x / h));
    std::int64_t iy = static_cast<std::int64_t>(std::floor(y / h));
    std::int64_t iz = static_cast<std::int64_t>(std::floor(z / h));
    const std::size_t p1 = 73856093u;
    const std::size_t p2 = 19349663u;
    const std::size_t p3 = 83492791u;
    return static_cast<std::size_t>((ix * static_cast<std::int64_t>(p1)) ^
                                    (iy * static_cast<std::int64_t>(p2)) ^
                                    (iz * static_cast<std::int64_t>(p3)));
};

std::for_each(std::execution::par,
              static_cast<std::size_t>(start),
